    s += (m.disp.value < 0n ? " - " : " + ") + immShort({ ...m.disp, value: m.disp.value < 0n ? -m.disp.value : m.disp.value });
  }
  return s;
}

/** 擬似コードの中で使う短い表記。 */
export function opShort(op) {
  if (!op) return "";
