const wrongWidth = explain('add', 'w8, w8, #4', 0x1004, pairCtx);
assert.equal(wrongWidth.target, null, 'a 32-bit add is not an address-building pair');
console.log('  ok 2 adrp+add pairs require a real register link (#1289)');

