const b = createRelocationBudget({ limits:{ maxOperations: 2 } });
b.step(1);
console.log('#1377 step(-1) ->', b.step(-1), '(expect false) | stopped', b.stopped);
const { createMachOMetadataBudget, MACHO_METADATA_LIMITS } = await import('./js/binary/macho-budget.js');
const m = createMachOMetadataBudget({metadata:{},warnings:[]}, { limits:{ records: NaN, wallClockMs: Infinity } });
console.log('#1376 records limit ->', m.limits.records, '(expect', MACHO_METADATA_LIMITS.records + ') | wallClockMs ->', m.limits.wallClockMs);
"; echo "=== full regression aggregate on merged main ==="; node tests/integrated-issues-hardening.mjs 2>&1 | grep -E "PASS$|ok [0-9]" | tail -12

for pr in 1384 1382 1380 1368; do echo "=== PR $pr ==="; gh pr view $pr --json files,state --jq '"\(.state) files: " + (.files|map(.path)|join(", "))'; done; echo "=== is LRU already fixed on main? ==="; node --input-type=module -e "
const { LRU } = await import('./js/lru.js');
for (const bad of [NaN, Infinity, -1]) {
  try { const l = new LRU(bad); l.set('a',1); l.set('b',2); console.log('LRU('+bad+') size after 2 sets =', l.size ?? l.map?.size ?? '?'); }
  catch(e){ console.log('LRU('+bad+') throws:', e.message.slice(0,50)); }
}
"

