/* Find identifiers called as functions that are never declared or imported in
   the same module. This is how the js/arm64.js memExpr/immShort/absHex defect
   was found: the calls existed, the definitions did not, and a swallowing
   catch made it look like "no description written yet". */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = '/workspaces/ida-245/js';
const KEYWORDS = new Set(['if','for','while','switch','catch','return','typeof','function','new','case','do','else','in','of','await','yield','delete','void','throw','instanceof','super','import','export','const','let','var','class','try','finally','default','with','debugger']);
const GLOBALS = new Set(Object.getOwnPropertyNames(globalThis));

function files(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === 'node_modules' || e.name.startsWith('.') || e.name === 'graft') continue;
    const full = path.join(dir, e.name);
    if (e.isDirectory()) files(full, out);
    else if (e.name.endsWith('.js')) out.push(full);
  }
  return out;
}

// Strip strings, template literals, comments and regex-ish literals so calls
// that only appear inside pseudocode text are not reported.
function strip(src) {
  let out = '', i = 0;
  while (i < src.length) {
    const c = src[i];
    if (c === '/' && src[i + 1] === '/') { while (i < src.length && src[i] !== '\n') i++; continue; }
    if (c === '/' && src[i + 1] === '*') { i += 2; while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) i++; i += 2; continue; }
    if (c === '"' || c === "'" || c === '`') {
      const q = c; i++;
      while (i < src.length && src[i] !== q) { if (src[i] === '\\') i++; i++; }
      i++; out += '""'; continue;
    }
    out += c; i++;
  }
  return out;
}

const report = [];
for (const file of files(ROOT)) {
  const raw = fs.readFileSync(file, 'utf8');
  const src = strip(raw);
  const declared = new Set();
  for (const m of src.matchAll(/(?:function|const|let|var|class)\s+([A-Za-z_$][\w$]*)/g)) declared.add(m[1]);
  for (const m of raw.matchAll(/import\s*\{([^}]*)\}/g)) for (const p of m[1].split(',')) { const n = p.trim().split(/\s+as\s+/).pop().trim(); if (n) declared.add(n); }
  for (const m of raw.matchAll(/import\s+([A-Za-z_$][\w$]*)\s*(?:,|from)/g)) declared.add(m[1]);
  for (const m of raw.matchAll(/import\s*\*\s*as\s+([A-Za-z_$][\w$]*)/g)) declared.add(m[1]);
  // parameters and destructuring targets, loosely
  for (const m of src.matchAll(/\(([^()]*)\)\s*(?:=>|\{)/g)) for (const p of m[1].split(',')) { const n = p.trim().replace(/[=:\[\]{}.].*/, '').trim(); if (/^[A-Za-z_$][\w$]*$/.test(n)) declared.add(n); }
  for (const m of src.matchAll(/(?:const|let|var)\s*\{([^}]*)\}/g)) for (const p of m[1].split(',')) { const n = p.trim().split(/[:=]/)[0].trim(); if (/^[A-Za-z_$][\w$]*$/.test(n)) declared.add(n); }
  for (const m of src.matchAll(/catch\s*\(\s*([A-Za-z_$][\w$]*)/g)) declared.add(m[1]);

  const missing = new Map();
  for (const m of src.matchAll(/(?<![.\w$?])([A-Za-z_$][\w$]*)\s*\(/g)) {
    const n = m[1];
    if (declared.has(n) || GLOBALS.has(n) || KEYWORDS.has(n)) continue;
    const line = raw.slice(0, m.index).split('\n').length;
    if (!missing.has(n)) missing.set(n, line);
  }
  for (const [n, line] of missing) report.push(`${path.relative('/workspaces/ida-245', file)}:${line}\t${n}`);
}
console.log(report.length ? report.join('\n') : 'no undefined call targets found');
console.log(`\nscanned ${files(ROOT).length} files, ${report.length} suspects`);
